using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The API path to query (e.g. \"/users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path.TrimStart('/'), cancellationToken);
        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text concisely.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional desired length: short, medium, or long.")] string length = "medium")
    {
        var systemInstruction = length switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key details.",
            _ => "Summarize the following text in a concise paragraph."
        };

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.System, systemInstruction),
            new(Microsoft.Extensions.AI.ChatRole.User, text)
        ];
    }
}

